S.append(goals(c,B,['Sắp xếp đúng <b>quy trình</b> xây dựng website.','Tổ chức <b>thư mục</b> và dùng <b>một CSS chung</b> cho nhiều trang.','Biết <b>kiểm thử</b> trên nhiều trình duyệt và thiết bị.','Nêu cách <b>xuất bản</b> và công cụ tạo trang (Google Sites).'],['Quy trình','Thư mục, CSS chung','Kiểm thử','Xuất bản']))
S.append(S2(c,B+' · 1','Quy trình xây dựng website',card('Các bước',STEPS(['<b>Xác định mục tiêu</b>, đối tượng người dùng, nội dung.','<b>Thiết kế</b>: sơ đồ trang, bố cục, màu sắc, phông chữ.','<b>Xây dựng</b>: viết HTML, CSS (và JavaScript).','<b>Kiểm thử</b>: lỗi, liên kết, hiển thị trên nhiều thiết bị.','<b>Xuất bản</b>: đưa lên máy chủ web, có địa chỉ truy cập.','<b>Bảo trì</b>: cập nhật nội dung, sửa lỗi.'])),FLOW([('Mục tiêu','phân tích'),('Thiết kế','bố cục'),('Xây dựng','HTML, CSS'),('Kiểm thử','sửa lỗi'),('Xuất bản','lên máy chủ')],520,'#1565C0',18)+KEY('Thứ tự: <b>phân tích → thiết kế → xây dựng → kiểm thử → xuất bản → bảo trì</b>.')))
S.append(S2(c,B+' · 1','Sơ đồ website và tổ chức thư mục',card('Cấu trúc gọn gàng',P('Lập <b>sơ đồ trang</b>: trang chủ liên kết tới các trang con.','Gom tệp theo loại: <b>css/</b>, <b>anh/</b>, <b>js/</b>; trang <b>index.html</b> là trang chủ.','Dùng <b>đường dẫn tương đối</b> để chuyển thư mục không hỏng liên kết.')),CODE('website/\n├── index.html\n├── gioithieu.html\n├── lienhe.html\n├── css/\n│   └── style.css\n└── anh/\n    └── logo.png',20)+KEY('Từ <b>gioithieu.html</b> nối CSS: <b>href="css/style.css"</b>.')))
S.append(S2(c,B+' · 2','Một tệp CSS dùng chung',card('Vì sao nên dùng chung?',P('Mọi trang cùng nối <b>một tệp style.css</b> bằng thẻ <b>link</b> trong head.','<b>Sửa một nơi, đổi cả website</b>: màu, phông, bố cục thống nhất.','Dễ bảo trì hơn viết CSS riêng trong từng trang.')),CODE('<!-- trong head của mọi trang -->\n<link rel="stylesheet"\n      href="css/style.css">',22)+KEY('Muốn giao diện giống nhau nhiều trang: <b>một tệp CSS ngoài</b> + thẻ <b>link</b>.')))
S.append(S2(c,B+' · 2','Bố cục trang phổ biến',card('Dùng thẻ ngữ nghĩa',P('<b>header</b> (đầu trang, logo), <b>nav</b> (menu), <b>main</b> (nội dung), <b>aside</b> (thanh bên), <b>footer</b> (chân trang).','Dùng <b>Flexbox</b> để chia cột; <b>@media</b> để đáp ứng điện thoại.')),BROWSER('<header>Logo – Tên website</header><nav>Trang chủ | Giới thiệu | Liên hệ</nav><div class="w"><main>Nội dung chính</main><aside>Thanh bên</aside></div><footer>Bản quyền © 2026</footer>','header{background:#1565C0;color:#fff;padding:8px}nav{background:#BBDEFB;padding:6px}.w{display:flex;gap:8px;margin:8px 0}main{flex:3;background:#C8E6C9;padding:10px}aside{flex:1;background:#FFE0B2;padding:10px}footer{background:#37474F;color:#fff;padding:6px;text-align:center}',h=210)))
S.append(S2(c,B+' · 3','Kiểm thử website',card('Cần kiểm tra gì?',ul(['<b>Liên kết</b>: không có liên kết hỏng (404).','<b>Hiển thị</b> trên nhiều trình duyệt (Chrome, Firefox, Edge…).','<b>Thiết bị</b>: máy tính, máy tính bảng, điện thoại.','<b>Chính tả</b>, ảnh tải được, <b>alt</b> đầy đủ.','<b>Tốc độ tải</b> và dung lượng ảnh.'],7)),KEY('Công cụ F12 (<b>DevTools</b>) của trình duyệt giúp xem phần tử, CSS áp dụng, lỗi và mô phỏng điện thoại.')))
S.append(S2(c,B+' · 4','Xuất bản website',card('Đưa lên Internet',P('Cần <b>tên miền</b> và <b>dịch vụ lưu trữ (hosting)</b>: thuê máy chủ hoặc dùng dịch vụ miễn phí.','Tải tệp của website lên máy chủ; người dùng truy cập bằng <b>URL</b>.','Kiểm tra lại sau khi xuất bản: <b>địa chỉ đúng, liên kết, ảnh</b>.')),T(tr('Cách','Ví dụ',h=True)+tr('viết mã thủ công','HTML, CSS, JS')+tr('<b>công cụ tạo trang trực tuyến</b>','Google Sites, Wix')+tr('hệ quản trị nội dung (CMS)','WordPress')+tr('lưu trữ miễn phí','GitHub Pages'))+KEY('Không cần viết mã: dùng <b>công cụ tạo trang như Google Sites</b>, kéo thả và xuất bản trực tuyến.')))
S.append(SELF(c,B+' · 5','Tự kiểm tra: sắp xếp bước','Sắp xếp theo thứ tự: (1) xuất bản; (2) xác định mục tiêu; (3) kiểm thử; (4) xây dựng bằng HTML, CSS; (5) thiết kế bố cục.','',P('<b>Đúng thứ tự: (2) → (5) → (4) → (3) → (1)</b>: mục tiêu → thiết kế → xây dựng → kiểm thử → xuất bản.'),20))
S.append(SELF(c,B+' · 5','Tự kiểm tra (HSG): đúng hay sai?','(a) Nhiều trang nối chung một tệp CSS ngoài. (b) Thẻ link đặt trong body. (c) Cần kiểm thử trên nhiều trình duyệt. (d) Google Sites cần viết mã HTML. (e) Dùng đường dẫn tương đối giúp chuyển thư mục không hỏng.','',P('(a) <b>Đúng</b>.','(b) <b>Sai</b>: link đặt trong <b>head</b>.','(c) <b>Đúng</b>.','(d) <b>Sai</b>: kéo thả, không cần viết mã.','(e) <b>Đúng</b>.'),20))
